using System.Runtime.CompilerServices;

namespace Lokad.Awk.Tests;

internal static partial class AwkGoldenCorpus
{
    // Names, parameters, initialization and field/stream effects were surveyed against
    // GNU 5.2.1 and 5.4.0 in C.UTF-8/UTC. Expectations select GNU 5.4/POSIX 2024;
    // diagnostics retain Lokad's stable prefix, wording and exit 2 normalization.
    // PROCINFO["FS"] transitions are covered separately by FieldModeCompatibilityCases.
    private static IEnumerable<AwkGoldenCase> ProfileNameCompatibilityCases() =>
        ExpandCompatibilityProfileCases("profile", NameAndControlProbes, 0)
            .Concat(ExpandCompatibilityProfileCases("profile", NameIntegrationProbes, NameAndControlProbes.Length * 3));

    private static IEnumerable<AwkGoldenCase> ExpandCompatibilityProfileCases(
        string family, CompatibilityProfileProbe[] probes, int firstId,
        [CallerFilePath] string sourceFile = "", [CallerLineNumber] int sourceLine = 0)
    {
        string?[] profiles = [null, "--posix", "--traditional"];
        foreach (var option in profiles)
        {
            foreach (var probe in probes)
            {
                var expected = option switch
                {
                    "--posix" => probe.PosixOnly ?? probe.PosixAndTraditional ?? probe.Default,
                    "--traditional" => probe.PosixAndTraditional ?? probe.Default,
                    _ => probe.Default
                };
                string[] arguments = option is null ? probe.Arguments : [option, .. probe.Arguments];
                var ordinal = (firstId++).ToString(System.Globalization.CultureInfo.InvariantCulture);
                var testCase = AwkGoldenCaseBuilder.Create($"{family}-{probe.Category}-{ordinal}", arguments, [], sourceFile, sourceLine)
                    .WithStandardInput(probe.Input).ExitsWith(expected.Exit)
                    .WithStdOut(expected.StdOut).WithStdErr(expected.StdErr).Build();
                yield return expected.CompilationRejected ? CompilerDiagnostic(testCase) : testCase;
            }
        }
    }

    private readonly record struct CompatibilityProfileProbe(string Category, string[] Arguments, string Input,
        CompatibilityProfileExpectation Default, CompatibilityProfileExpectation? PosixAndTraditional = null,
        CompatibilityProfileExpectation? PosixOnly = null);

    private readonly record struct CompatibilityProfileExpectation(int Exit, string StdOut,
        string StdErr = "", bool CompilationRejected = false);

    private sealed record ProfileNameRow(string Name, string[] Arguments, string Input,
        int Exit, string StdOut, string StdErr, bool CompilationRejected);

